contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable {
        require(amount > 0, "zero amount");

        address receiver = address(this);
        uint256 cBalBefore = address(c).balance;
        uint256 recvBalBefore = receiver.balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            (reverted && address(c).balance == cBalBefore && receiver.balance == recvBalBefore) ||
            (!reverted && address(c).balance == cBalBefore - amount && receiver.balance == recvBalBefore + amount)
        );
    }
}

