pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount > 0);
        address receiver = address(this);
        uint256 cBalBefore = address(c).balance;
        uint256 recvBalBefore = receiver.balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((reverted && address(c).balance == cBalBefore && receiver.balance == recvBalBefore) ||
            (!reverted && address(c).balance == cBalBefore - amount && receiver.balance == recvBalBefore + amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
